def paginate(items, page_size):
    """Split `items` into consecutive pages of at most `page_size` items."""
    if page_size <= 0:
        raise ValueError("page_size must be positive")
    num_pages = -(-len(items) // page_size)  # ceiling division keeps the final partial page
    return [items[i * page_size : (i + 1) * page_size] for i in range(num_pages)]

